alter table profiles add column if not exists notify_email text; do $$ begin alter table public.profiles add constraint profiles_notify_email_shape check ( notify_email is null or notify_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' ); exception when duplicate_object then null; end $$; create or replace function public.notify_new_version() returns trigger language plpgsql security definer set search_path = public as $$ declare parent record; client_name text; recipient uuid; begin select s.id, s.title, s.client_id, s.created_by, s.visibility into parent from public.submissions s where s.id = new.submission_id; if parent.id is null then return new; end if; select name into client_name from public.clients where id = parent.client_id; for recipient in select p.id from public.profiles p where p.role = 'ceo' union select cs.staff_id from public.client_staff cs join public.profiles p on p.id = cs.staff_id where cs.client_id = parent.client_id and p.role in ('operations_manager', 'staff') loop perform public.notify_user( recipient, 'upload_new_version', case when new.version = 1 then 'New upload: ' || parent.title else 'New cut (v' || new.version || '): ' || parent.title end, concat_ws(' ' || chr(183) || ' ', client_name, 'ready to review'), '/app/uploads' ); end loop; if parent.visibility = 'team_and_client' and new.version > 1 then for recipient in select id from public.profiles where role = 'client' and client_id = parent.client_id loop perform public.notify_user( recipient, 'upload_new_version_client', 'An updated cut of "' || parent.title || '" is ready', 'Version ' || new.version || ' is on your Uploads tab.', '/app/portal/uploads' ); end loop; end if; return new; end; $$; drop trigger if exists submission_versions_notify on submission_versions; create trigger submission_versions_notify after insert on submission_versions for each row execute procedure public.notify_new_version();
